 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marked = set()
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            marked.update((r, c) for c in range(w))
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            v = next(iter(vals))
            if v != background:
                marked.update((r, c) for r in range(h))
    out = [row[:] for row in grid]
    for r, c in marked:
        out[r][c] = 2
    return out
